59	async function loadServer(job: Job): Promise<Server & { plan: any; osTemplate: any; node: any }> {
60	  const server = await db.server.findUnique({
61	    where: { id: job.serverId! },
62	    include: { plan: true, osTemplate: true, node: true },
63	  });
64	  if (!server) throw new Error(`Server ${job.serverId} not found`);
65	  return server as any;
66	}
