331	async function powerAction(job: Job, action: "start" | "stop" | "reboot") {
332	  const server = await loadServer(job);
333	  if (SANDBOX) {
334	    await db.server.update({
335	      where: { id: server.id },
336	      data: { status: action === "stop" ? "STOPPED" : "RUNNING" },
337	    });
338	    return;
339	  }
340	  const { conn } = await nodeFor(server);
341	  const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/${action}`, {});
342	  await conn.waitForTask(upid);
343	  await db.server.update({
344	    where: { id: server.id },
345	    data: { status: action === "stop" ? "STOPPED" : "RUNNING" },
346	  });
347	}
348	
349	async function destroyVm(conn: any, vmid: number) {
350	  // Stop first (ignore failure if already stopped), then destroy
351	  try {
352	    const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/stop`, {});
353	    await conn.waitForTask(stopUpid);
354	  } catch {
355	    /* already stopped or does not exist */
356	  }
357	  const delUpid = await conn.del(`/nodes/${conn.node}/qemu/${vmid}`, {
358	    "destroy-unreferenced-disks": 1,
359	    purge: 1,
360	  });
361	  await conn.waitForTask(delUpid, 600_000);
362	}
363	
364	async function remove(job: Job) {
365	  const server = await loadServer(job);
366	  const { conn } = await nodeFor(server);
367	  if (!SANDBOX && server.vmid) {
368	    try {
369	      await destroyVm(conn, server.vmid);
370	    } catch (e: any) {
371	      // VM may never have been created; only swallow "does not exist"
372	      if (!String(e?.body ?? e?.message).includes("does not exist")) throw e;
373	    }
374	    // Best-effort: remove the per-server cloud-init snippet
375	    await unlink(`${SNIPPET_DIR}/nxeon-${server.vmid}.yaml`).catch(() => {});
376	  }
377	  // Return any dedicated IP to the pool (deletes the OVH Virtual MAC).
378	  if (!SANDBOX) await releaseDedicatedIp(server.id).catch((e) => console.error("[worker] release dedicated IP failed", e));
379	  // Any block-storage volume disk (vm-<vmid>-disk-N) was purged with the VM above.
380	  // Volume.server is SetNull, so the rows would otherwise survive with a dead
381	  // diskName and keep billing forever. Remove them and notify the owner. (The
382	  // reinstall guard already blocks the accidental case; a full server delete is an
383	  // intentional teardown, so we drop the volumes with it.)
384	  const orphanVolumes = await db.volume.findMany({ where: { serverId: server.id } });
385	  if (orphanVolumes.length > 0) {
386	    await db.volume.deleteMany({ where: { serverId: server.id } });
387	    for (const v of orphanVolumes) {
388	      await notify(
389	        v.userId,
390	        `Volume "${v.name}" was removed`,
391	        `${v.sizeGB} GB block storage was deleted along with server ${server.hostname}. Billing for it has stopped.`,
392	        "/dashboard/volumes",
393	      ).catch(() => {});
394	    }
395	  }
396	  // Detach this DELETE job (and any siblings) from the server FIRST, otherwise the
397	  // server.delete cascade removes THIS running Job row — the success-path
398	  // `job.update({id})` then throws P2025 and escapes runJob. Null serverId instead.
399	  await db.job.updateMany({ where: { serverId: server.id }, data: { serverId: null } });
400	  await db.server.delete({ where: { id: server.id } });
401	  if (!SANDBOX) await syncPortForwards();
402	}
403	
404	async function reinstall(job: Job) {
405	  const server = await loadServer(job);
406	  if (SANDBOX) {
407	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
408	    await notify(
409	      server.userId,
410	      `Server ${server.hostname} reinstalled (sandbox)`,
411	      "The sandbox server was reinstalled (no real VM was touched).",
412	      `/dashboard/servers/${server.id}`
413	    );
414	    return;
415	  }
416	  // DATA SAFETY (critical): a reinstall destroys the VM, and `destroyVm` runs
417	  // `qm destroy` with { "destroy-unreferenced-disks": 1, purge: 1 } — which wipes
418	  // EVERY disk the vmid owns, including attached block-storage Volume disks
419	  // (scsi1+, `vmdata:vm-<vmid>-disk-N`). A disk named `vm-<vmid>-disk-N` is owned
420	  // by that vmid, and both purge and the default destroy (which removes disks
421	  // referenced in config, incl. detached `unusedN` entries) delete it; there is no
422	  // Proxmox API to selectively spare it, and the reinstall re-clones onto the SAME
423	  // vmid, so we cannot GUARANTEE such a disk survives the destroy. Rather than risk
424	  // wiping a customer's data, BLOCK the reinstall until the volume(s) are detached.
425	  // Detaching moves the disk to an "unused" entry (data preserved on storage) and it
426	  // can be re-attached after the reinstall. This runs BEFORE any status change or
427	  // destructive call, so a blocked reinstall touches nothing.
428	  //
429	  // Match on `serverId` ALONE — NOT `status: "ATTACHED"`. Detaching keeps
430	  // `serverId` set (see worker/volumes.ts) so the volume can be re-attached, and
431	  // the disk remains owned by this vmid as an `unusedN` entry. PVE's destroy_vm
432	  // passes `include_unused => 1`, so it frees those too. Filtering on ATTACHED
433	  // let the worst path through: fill a volume, Detach (the UI says "Data is
434	  // preserved."), Reinstall — guard sees nothing attached, purge takes the data.
435	  // Detaching is therefore NOT sufficient protection, and telling the customer to
436	  // detach was wrong advice; they must delete the volume (which destroys just
437	  // that disk, deliberately) or move it to another server first.
438	  const pinnedVolumes = await db.volume.findMany({
439	    where: { serverId: server.id },
440	  });
441	  // Sandbox volumes have no real disk, so they cannot be purged and must not block.
442	  const realPinned = pinnedVolumes.filter(
443	    (v) => !(typeof v.diskName === "string" && v.diskName.startsWith("sandbox:"))
444	  );
445	  if (realPinned.length > 0) {
446	    const names = realPinned.map((v) => `"${v.name}"`).join(", ");
447	    throw new Error(
448	      `Remove your data volume(s) before reinstalling to protect their data: ${names}. ` +
449	        `Reinstalling purges every disk this server owns — including detached volumes ` +
450	        `that are still assigned to it — and that cannot be undone.`
451	    );
452	  }
453	
454	  const { conn } = await nodeFor(server);
455	  await db.server.update({ where: { id: server.id }, data: { status: "REINSTALLING" } });
456	  if (server.vmid) await destroyVm(conn, server.vmid);
457	  await provision(job);
458	}
