658	      `/dashboard/servers/${server.id}`
659	    );
660	    return;
661	  }
662	  if (!server.vmid) throw new Error("password reset: server has no VM yet");
663	  const { conn } = await nodeFor(server);
664	  const password = generatePassword();
665	
666	  // Preferred path: set it live via the qemu-guest-agent (no reboot needed).
667	  let applied = false;
