882	/**
883	 * Reverse a money side-effect that a job committed up-front but never delivered.
884	 * Server actions charge/credit the wallet before enqueuing the worker job (so the
885	 * UI reflects the change immediately); if the job then fails terminally the money
886	 * must be unwound or the customer is charged for a resize that never happened
887	 * (up) or keeps a downgrade credit for hardware they still have (down).
888	 * Idempotent per job: guarded by the RECONCILED audit marker so a re-run can't
889	 * double-reverse.
890	 */
891	async function reconcileFailedJob(job: Job) {
892	  if (job.type === "DISK_EXPAND") return reconcileFailedDiskExpand(job);
893	  if (job.type !== "RESIZE") return;
894	  const p = (job.payload ?? {}) as { prorateCents?: number; direction?: "up" | "down" };
895	  const cents = p.prorateCents ?? 0;
896	  if (cents <= 0 || !job.serverId) return;
897	
898	  // Idempotency: skip if we already reversed this exact job.
899	  const already = await db.auditLog.findFirst({
900	    where: { action: "server.resize.reconcile", detail: { contains: `job=${job.id}` } },
901	  });
902	  if (already) return;
903	
904	  const server = await db.server.findUnique({ where: { id: job.serverId }, select: { userId: true, hostname: true } });
905	  if (!server) return;
906	
907	  try {
908	    if (p.direction === "up") {
909	      // Upgrade charge never delivered → refund the prorated charge.
910	      await db.$transaction([
911	        db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
912	        db.walletTransaction.create({
913	          data: { userId: server.userId, amountCents: cents, description: `Refund: failed upgrade — ${server.hostname}` },
914	        }),
915	      ]);
916	    } else if (p.direction === "down") {
917	      // Downgrade credit was given but hardware unchanged → claw the credit back.
918	      // Guarded so it can never drive the balance negative; if the customer already
919	      // spent it, we log and leave it (best-effort — they keep a small windfall).
920	      await db.$transaction(async (tx) => {
921	        await debitWallet(tx, server.userId, cents);
922	        await tx.walletTransaction.create({
923	          data: { userId: server.userId, amountCents: -cents, description: `Reversed downgrade credit (resize failed) — ${server.hostname}` },
924	        });
925	      });
926	    }
927	    await db.auditLog.create({
928	      data: { userId: server.userId, action: "server.resize.reconcile", detail: `job=${job.id} dir=${p.direction} cents=${cents}` },
929	    });
930	  } catch (e: any) {
931	    // InsufficientBalanceError on a down-reversal is expected/acceptable; record it.
932	    await db.auditLog.create({
933	      data: { userId: server.userId, action: "server.resize.reconcile.uncharged", detail: `job=${job.id} dir=${p.direction} cents=${cents} :: ${e?.message ?? e}` },
934	    }).catch(() => {});
935	  }
936	}
