132	// ---------- 3. Resize-down ----------
133	
134	/**
135	 * Move a server to a SMALLER (cheaper) plan. CPU/RAM can shrink freely, but the
136	 * disk can NOT shrink on the hypervisor, so we require the target plan's disk to
137	 * be >= the current plan's disk (the worker's RESIZE handler hard-fails a shrink
138	 * otherwise). A prorated credit for the price difference over the remaining term
139	 * is returned to the wallet.
140	 */
141	export async function resizeServerDown(
142	  serverId: string,
143	  newPlanId: string
144	): Promise<{ error?: string }> {
145	  const { user, server } = await ownedServer(serverId);
146	
147	  const newPlan = await db.plan.findUnique({ where: { id: newPlanId } });
148	  if (!newPlan?.active) return { error: "Plan not available." };
149	  if (newPlan.id === server.planId) return { error: "Server is already on this plan." };
150	  if (!["RUNNING", "STOPPED"].includes(server.status)) return { error: "Server is busy." };
151	
152	  // This action is downgrades only — upgrades go through resizeServer().
153	  if (newPlan.priceCents >= server.plan.priceCents) {
154	    return { error: "This is not a smaller plan — use the upgrade flow instead." };
155	  }
156	  // Disk can't shrink destructively; block the move rather than lose data.
157	  // Compares PLAN disks on purpose: any purchased `extraDiskGB` is additive to
158	  // both the old and the new plan and is preserved verbatim across the resize, so
159	  // "new plan disk >= old plan disk" is exactly the condition for "effective disk
160	  // does not shrink". Nothing here ever writes extraDiskGB.
161	  if (newPlan.diskGB < server.plan.diskGB) {
162	    return {
163	      error: `Disk can't shrink — ${newPlan.name} has a ${newPlan.diskGB} GB disk but your server uses ${server.plan.diskGB} GB. Pick a smaller plan whose disk is at least ${server.plan.diskGB} GB.`,
164	    };
165	  }
166	
167	  if (await hasInflightJob(serverId)) {
168	    return { error: "Another operation is already in progress on this server." };
169	  }
170	
171	  // Credit at the SAME effective rate the upgrade path charges at — term discount
172	  // and promo applied — and clamp the remaining months to one term.
173	  //
174	  // The old maths credited the raw LIST-price delta over an UNCLAMPED duration,
175	  // so it refunded more than the customer had ever paid (they bought at the
176	  // term-discounted, promo-reduced price) and multiplied that by every month a
177	  // stacked `renewNow` had pushed `expiresAt` into the future. On a 36-month term
178	  // that is roughly a 20% cash windfall per downgrade before any promo. It has
179	  // been unreachable only because the disk-monotonic guard blocks every downgrade
180	  // the live catalogue permits — one cheap, storage-heavy plan would have turned
181	  // it into a self-service money printer. Shared with the upgrade path through
182	  // lib/proration.ts so the two directions can never drift apart again.
183	  let creditCents = 0;
184	  if (!server.isFree && server.expiresAt) {
185	    creditCents = prorateDowngradeCreditCents({
186	      fromMonthlyCents: server.plan.priceCents,
187	      toMonthlyCents: newPlan.priceCents,
188	      termMonths: server.termMonths,
189	      monthsRemaining: remainingMonths(server.expiresAt, Date.now(), server.termMonths),
190	    });
191	  }
192	
193	  await db.$transaction([
194	    ...(creditCents > 0
195	      ? [
196	          db.user.update({
197	            where: { id: server.userId },
198	            data: { balanceCents: { increment: creditCents } },
199	          }),
200	          db.walletTransaction.create({
201	            data: {
202	              userId: server.userId,
203	              amountCents: creditCents,
204	              description: `Downgrade to ${newPlan.name} (prorated credit) — ${server.hostname}`,
205	            },
206	          }),
207	        ]
208	      : []),
209	    // Record the amount credited on the job so the worker's RESIZE handler can
210	    // REVERSE it (re-debit `payload.prorateCents` from the wallet) if the resize
211	    // terminally fails — the credit is committed here, before the job runs.
212	    // INTEGRATION NEEDED: worker must honour payload.prorateCents/direction.
213	    db.job.create({
214	      data: {
215	        type: "RESIZE",
216	        serverId,
217	        payload: { planId: newPlan.id, prorateCents: creditCents, direction: "down" } as any,
218	      },
219	    }),
220	    db.auditLog.create({
221	      data: {
222	        userId: user.id,
223	        action: "server.resize_down",
224	        detail: `${serverId} -> ${newPlan.slug} credit=${creditCents}`,
225	      },
226	    }),
227	  ]);
228	
229	  revalidatePath(`/dashboard/servers/${serverId}`);
230	  return {};
231	}
