12	/**
13	 * Post-deploy "Add storage": grow ONE server's own root disk by N GB without
14	 * changing its plan (CPU/RAM/plan price are untouched).
15	 *
16	 * Money path is a carbon copy of lib/actions-server.ts resizeServer:
17	 *   quote -> walletSplit -> (card remainder ? Stripe checkout : apply now).
18	 * The wallet is only ever debited by applyDiskExpand, and only after the card
19	 * portion has cleared, so displayed === charged and nothing is charged twice.
20	 *
21	 * GROWTH IS ONE-WAY. There is deliberately no companion "shrink" action.
22	 */
23	
24	/** Max expansions a single customer may start in RATE_WINDOW_MS. */
25	const MAX_EXPANDS_PER_WINDOW = 5;
26	const RATE_WINDOW_MS = 10 * 60_000;
27	
28	async function ownedServer(serverId: string) {
29	  const user = await requireUser();
30	  const server = await db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
31	  if (!server) throw new Error("Not found");
32	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
33	  return { user, server };
34	}
35	
36	export async function expandServerDisk(
37	  serverId: string,
38	  addGB: number,
39	  useWallet: boolean = true,
40	): Promise<{ error?: string; checkoutUrl?: string }> {
41	  // Spend path: block wallet debits while an admin is impersonating.
42	  await assertNotImpersonating();
43	  const { user, server } = await ownedServer(serverId);
44	
45	  // Round DOWN to a purchasable amount — a malformed value can only ever cost
46	  // the customer less, never more (see normalizeExtraDiskGB).
47	  const gb = normalizeExtraDiskGB(addGB);
48	  if (gb <= 0) return { error: "Choose an amount of storage to add." };
49	
50	  // Rate limit: expansions are irreversible and each one queues real hypervisor
51	  // work, so cap how fast a single account can fire them off.
52	  const recent = await db.job.count({
53	    where: {
54	      type: "DISK_EXPAND",
55	      createdAt: { gt: new Date(Date.now() - RATE_WINDOW_MS) },
56	      server: { userId: user.id },
57	    },
58	  });
59	  if (recent >= MAX_EXPANDS_PER_WINDOW) {
60	    return { error: "Too many storage expansions just now — please wait a few minutes and try again." };
61	  }
62	
63	  // Reject while another job is in flight, and only from a steady run state.
64	  // (applyDiskExpand re-checks both; this returns the friendlier message first.)
65	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
66	    return { error: "Server must be running or stopped to add storage." };
67	  }
68	  const pending = await db.job.count({
69	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
70	  });
71	  if (pending > 0) return { error: "Another operation is already in progress on this server." };
72	
73	  // Validate + price the expansion (ownership already checked above).
74	  let quote;
75	  try {
76	    quote = await diskExpandQuote(serverId, gb);
77	  } catch (e) {
78	    if (e instanceof DiskExpandError) return { error: e.message };
79	    throw e;
80	  }
81	  const { prorateCents } = quote;
82	
83	  // Wallet-aware split — identical logic to the deploy/resize flows. AddStorage
84	  // computes the same split (lib/wallet-split.ts) so displayed === charged.
85	  const { cardCents } = walletSplit({
86	    dueCents: prorateCents,
87	    balanceCents: user.balanceCents,
88	    useWallet,
89	  });
90	
91	  // Card portion > 0 → charge ONLY the remainder on the card. The confirm route
92	  // credits the card amount to the wallet and then debits the FULL proration
93	  // (encoded as chargeCents), so the wallet absorbs its share and the card the
94	  // rest — the wallet is never touched before the card clears.
95	  if (cardCents > 0) {
96	    const url = await createDiskExpandCheckout(user, cardCents, {
97	      serverId,
98	      addGB: gb,
99	      hostname: server.hostname,
100	      prorateCents,
101	    });
102	    if (!url) {
103	      return {
104	        error: `Adding ${gb} GB costs $${(prorateCents / 100).toFixed(2)} for the rest of your term, and card payments aren't set up — top up your wallet first.`,
105	      };
106	    }
107	    return { checkoutUrl: url };
108	  }
109	
110	  // Card portion is $0 (wallet fully covers it, or the charge is $0 for free/admin
111	  // servers) → apply instantly, debiting the full proration from the wallet.
112	  try {
113	    await applyDiskExpand({ serverId, addGB: gb, actorUserId: user.id });
114	  } catch (e) {
115	    if (e instanceof DiskExpandError) return { error: e.message };
116	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
117	    throw e;
118	  }
119	  revalidatePath(`/dashboard/servers/${serverId}`);
120	  return {};
121	}
