130	/**
131	 * Apply the expansion: (optionally) debit the wallet for the prorated charge,
132	 * record the wallet transaction + PAID invoice, and queue the DISK_EXPAND job the
133	 * worker performs on Proxmox + inside the guest. Re-validates every guard (size,
134	 * ceiling, steady state, one in-flight job) so it is safe to call from the
135	 * unauthenticated confirm route. Throws DiskExpandError on any guard failure.
136	 *
137	 * `chargeCents` overrides the recomputed proration — the paid path passes the
138	 * exact amount the customer paid into their wallet at checkout so the debit here
139	 * nets to zero against that credit (mirrors lib/resize.ts applyResize).
140	 *
141	 * NOTE: `Server.extraDiskGB` is deliberately NOT advanced here. The worker sets it
142	 * only after the disk really grew, so a failed job is refunded (see
143	 * reconcileFailedJob) and no renewal ever bills for space that wasn't delivered.
144	 */
145	export async function applyDiskExpand(opts: {
146	  serverId: string;
147	  addGB: number;
148	  actorUserId: string;
149	  chargeCents?: number;
150	}): Promise<void> {
151	  const quote = await diskExpandQuote(opts.serverId, opts.addGB);
152	  const { server, addGB, targetExtraDiskGB, newTotalDiskGB, monthlyCents } = quote;
153	  const prorateCents = opts.chargeCents ?? quote.prorateCents;
154	
155	  const pending = await db.job.count({
156	    where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
157	  });
158	  if (pending > 0) throw new DiskExpandError("Another operation is already in progress on this server.");
159	
160	  const label = extraDiskLabel(addGB);
161	  try {
162	    await db.$transaction(async (tx) => {
163	      if (prorateCents > 0) {
164	        await debitWallet(tx, server.userId, prorateCents);
165	        await tx.walletTransaction.create({
166	          data: {
167	            userId: server.userId,
168	            amountCents: -prorateCents,
169	            description: `${label} (prorated) — ${server.hostname}`,
170	          },
171	        });
172	        // PAID invoice for the proration. The line item spells out BOTH the
173	        // permanence and the recurring monthly cost, so the billing document
174	        // itself carries the one-way warning.
175	        await tx.invoice.create({
176	          data: invoiceCreateData({
177	            userId: server.userId,
178	            description: `${label} (prorated) — ${server.hostname}`,
179	            status: "PAID",
180	            lineItems: [
181	              {
182	                description:
183	                  `${label} — prorated for remaining term (${server.hostname}). ` +
184	                  `Disk grows to ${newTotalDiskGB} GB permanently; renews at $${(monthlyCents / 100).toFixed(2)}/mo.`,
185	                qty: 1,
186	                unitCents: prorateCents,
187	                amountCents: prorateCents,
188	              },
189	            ],
190	          }),
191	        });
192	      }
193	      // Record the amount charged AND the target on the job so the worker can
194	      // (a) know how far to grow and (b) REVERSE the charge if the expansion
195	      // terminally fails — money is committed here, before the job runs.
196	      await tx.job.create({
197	        data: {
198	          type: "DISK_EXPAND",
199	          serverId: server.id,
200	          payload: { addGB, targetExtraDiskGB, prorateCents, monthlyCents } as any,
201	        },
202	      });
203	      await tx.auditLog.create({
204	        data: {
205	          userId: opts.actorUserId,
206	          action: "server.disk_expand",
207	          detail: `${server.id} +${addGB}GB -> extra=${targetExtraDiskGB} total=${newTotalDiskGB} prorate=${prorateCents}`,
208	        },
209	      });
210	    });
211	  } catch (e) {
212	    if (e instanceof InsufficientBalanceError) {
213	      throw new DiskExpandError("Insufficient balance — top up your wallet first.");
214	    }
215	    throw e;
216	  }
217	}
