283	export async function diskExpand(job: Job): Promise<void> {
284	  const payload = (job.payload ?? {}) as { addGB?: number; targetExtraDiskGB?: number };
285	  const addGB = Math.round(Number(payload.addGB ?? 0));
286	  if (!Number.isInteger(addGB) || addGB <= 0) throw new Error("disk expand: invalid addGB");
287	
288	  const server = await db.server.findUnique({
289	    where: { id: job.serverId! },
290	    include: { plan: true, node: true, dedicatedIp: true },
291	  });
292	  if (!server) throw new Error(`Server ${job.serverId} not found`);
293	
294	  // Target is recorded on the job at purchase time so a concurrent write can't
295	  // move the goalposts; fall back to "current + addGB" for older payloads.
296	  const targetExtraDiskGB = Math.max(
297	    server.extraDiskGB,
298	    Math.round(Number(payload.targetExtraDiskGB ?? server.extraDiskGB + addGB)),
299	  );
300	  const targetTotalGB = effectiveDiskGB(server.plan.diskGB, targetExtraDiskGB);
301	  const link = `/dashboard/servers/${server.id}`;
302	  const step = (pct: number, s: string) => reportJobProgress(job.id, pct, s);
303	
304	  if (SANDBOX) {
305	    // Simulate the whole sequence — no Proxmox call, no SSH — but exercise the
306	    // real progress bar and persist the purchased storage so billing is exact.
307	    for (const s of [
308	      { pct: 8, step: "Checking current disk size" },
309	      { pct: 30, step: `Growing the virtual disk to ${targetTotalGB} GB` },
310	      { pct: 60, step: "Connecting to the server" },
311	      { pct: 85, step: "Growing the root partition" },
312	      { pct: 95, step: "Growing the filesystem" },
313	    ]) {
314	      await step(s.pct, s.step);
315	      await new Promise((r) => setTimeout(r, 400));
316	    }
317	    await db.server.update({ where: { id: server.id }, data: { extraDiskGB: targetExtraDiskGB } });
318	    await step(100, "Storage expanded");
319	    await notify(
320	      server.userId,
321	      `${server.hostname}: storage expanded to ${targetTotalGB} GB`,
322	      `Sandbox expansion of +${addGB} GB completed (no real VM was touched). Added storage is permanent.`,
323	      link,
324	    );
325	    return;
326	  }
327	
328	  if (!server.vmid) throw new Error("disk expand: server has no VM yet");
329	  const { conn } = await nodeFor(server);
330	
331	  // 1. What size is the disk RIGHT NOW? (Authoritative — survives retries.)
332	  await step(5, "Checking current disk size");
333	  const cfg = await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`);
334	  const currentGB = parseDiskSizeGB(cfg?.scsi0);
335	  if (currentGB == null) throw new Error("disk expand: could not read the current scsi0 disk size");
336	
337	  // 2. Grow on the hypervisor — ONLY when it isn't already big enough. A retry
338	  //    after a crash lands here with the disk already grown and skips straight
339	  //    to the guest-side grow (idempotent, never shrinks).
340	  const deltaGB = targetTotalGB - currentGB;
341	  if (deltaGB > 0) {
342	    await step(15, `Growing the virtual disk to ${targetTotalGB} GB`);
343	    // Proxmox accepts only a POSITIVE delta here ("+NG") and refuses to shrink.
344	    const upid = await conn.put(`/nodes/${conn.node}/qemu/${server.vmid}/resize`, {
345	      disk: "scsi0",
346	      size: `+${deltaGB}G`,
347	    });
348	    if (typeof upid === "string" && upid.startsWith("UPID")) {
349	      await step(30, "Waiting for the hypervisor");
350	      await conn.waitForTask(upid, 600_000);
351	    }
352	  } else {
353	    console.log(`[disk-expand] vmid ${server.vmid} already ${currentGB}G >= ${targetTotalGB}G — skipping Proxmox resize`);
354	  }
355	
356	  // 3. Grow the guest filesystem ONLINE. A failure here is NOT a job failure —
357	  //    the space is already paid for and already attached.
358	  let warn: { reason: string; commands: string } | null = null;
359	  if (server.status !== "RUNNING") {
360	    warn = {
361	      reason: "the server is powered off",
362	      commands: manualCommands(null),
363	    };
364	  } else {
365	    await step(55, "Connecting to the server");
366	    warn = await growGuestFilesystem(server, step);
367	  }
368	
369	  // 4. Persist the purchased storage. Done AFTER the disk really grew, so a
370	  //    terminal failure before this point is refunded by the worker's reconcile
371	  //    pass and never renews.
372	  await db.server.update({ where: { id: server.id }, data: { extraDiskGB: targetExtraDiskGB } });
373	
374	  if (warn) {
375	    await step(100, `Disk grown to ${targetTotalGB} GB — filesystem needs a manual grow`);
376	    await notify(
377	      server.userId,
378	      `${server.hostname}: disk grown to ${targetTotalGB} GB — one step left`,
379	      `We added ${addGB} GB and your virtual disk is now ${targetTotalGB} GB, but we couldn't expand the filesystem automatically because ${warn.reason}. ` +
380	        (server.status !== "RUNNING"
381	          ? "Most images grow the filesystem by themselves on the next boot — just start the server. If it doesn't, "
382	          : "") +
383	        `SSH in as root and run:\n\n    ${warn.commands}\n\nThen \`df -h /\` will show the full ${targetTotalGB} GB. Added storage is permanent for this server's lifetime.`,
384	      link,
385	    );
386	    console.warn(`[disk-expand] ${server.hostname}: online grow skipped — ${warn.reason}`);
387	    return;
388	  }
389	
390	  await step(100, `Storage expanded to ${targetTotalGB} GB`);
391	  await notify(
392	    server.userId,
393	    `${server.hostname}: storage expanded to ${targetTotalGB} GB`,
