71	/** Strip Proxmox disk options: "vmdata:vm-101-disk-1,size=10G" -> "vmdata:vm-101-disk-1". */
72	function volidOf(configValue: unknown): string {
73	  return String(configValue ?? "").split(",")[0].trim();
74	}
75	
76	/**
77	 * True for a real Proxmox disk volid such as "vmdata:vm-102-disk-1" (or a
78	 * file/dir volid like "vmdata:102/vm-102-disk-1.raw"). Used to reject empty/
79	 * garbage read-backs so `Volume.diskName` is never persisted as a non-volid.
80	 */
81	function isRealVolid(v: unknown): v is string {
82	  return typeof v === "string" && /^[^,\s:]+:\S*vm-\d+-disk-\d+/.test(v.trim());
83	}
84	
85	/** All disk volids currently referenced by a VM config (scsi/virtio/ide/sata/unused). */
86	function diskVolids(config: Record<string, any>): string[] {
87	  const out: string[] = [];
88	  for (const [k, v] of Object.entries(config)) {
89	    if (typeof v !== "string") continue;
90	    if (!/^(scsi|virtio|ide|sata|unused)\d+$/.test(k)) continue;
91	    const id = volidOf(v);
92	    if (isRealVolid(id)) out.push(id);
93	  }
94	  return out;
95	}
96	
97	/** First free scsiN slot (scsi0 is the OS disk). Proxmox supports scsi0..scsi30. */
98	function freeScsiSlot(config: Record<string, any>): string {
99	  for (let i = 1; i <= 30; i++) {
100	    if (config[`scsi${i}`] === undefined) return `scsi${i}`;
101	  }
102	  throw new Error("no free scsi slot available on this VM");
103	}
104	
105	/** Find the config key (scsiN / unusedN / …) that currently references `volid`. */
106	function keyForVolid(config: Record<string, any>, volid: string): string | null {
107	  for (const [k, v] of Object.entries(config)) {
108	    if (typeof v === "string" && volidOf(v) === volid) return k;
109	  }
110	  return null;
111	}
112	
113	/**
114	 * VOLUME_CREATE — logical registration only. No physical disk is created until
115	 * the volume is first attached (a Proxmox disk must live on a VM). Flip the row
116	 * from PENDING to DETACHED so the customer can attach it.
117	 */
118	export async function volumeCreate(job: Job): Promise<void> {
119	  const volume = await loadVolume(job);
120	  if (volume.status === "PENDING") {
121	    await db.volume.update({ where: { id: volume.id }, data: { status: "DETACHED" } });
122	  }
123	  await notify(
124	    volume.userId,
125	    `Volume "${volume.name}" is ready`,
126	    `${volume.sizeGB} GB block storage is available to attach to a server.`,
127	    "/dashboard/volumes"
128	  );
129	}
