209	/**
210	 * VOLUME_DETACH — detach the disk from the VM (Proxmox moves it to an "unused"
211	 * entry, preserving the data). The volume stays pinned to this server so it can
212	 * be re-attached here later.
213	 */
214	export async function volumeDetach(job: Job): Promise<void> {
215	  const volume = await loadVolume(job);
216	  const server = volume.server;
217	
218	  if (SANDBOX) {
219	    await db.volume.update({ where: { id: volume.id }, data: { status: "DETACHED" } });
220	    if (server) {
221	      await notify(
222	        volume.userId,
223	        `Volume "${volume.name}" detached from ${server.hostname}`,
224	        "The volume and its data are preserved and can be re-attached (sandbox).",
225	        "/dashboard/volumes"
226	      );
227	    }
228	    return;
229	  }
230	
231	  if (server?.vmid && volume.diskName) {
232	    const { conn } = await nodeFor(server);
233	    const config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
234	    const key = keyForVolid(config, volume.diskName);
235	    if (key && key.startsWith("scsi")) {
236	      await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
237	    }
238	  }
239	
240	  await db.volume.update({ where: { id: volume.id }, data: { status: "DETACHED" } });
241	  if (server) {
242	    await notify(
243	      volume.userId,
244	      `Volume "${volume.name}" detached from ${server.hostname}`,
245	      "The volume and its data are preserved and can be re-attached to the same server.",
246	      "/dashboard/volumes"
247	    );
248	  }
249	}
250	
251	/**
252	 * VOLUME_DELETE — detach (if attached) then permanently destroy the underlying
253	 * disk, and remove the Volume row.
254	 */
255	export async function volumeDelete(job: Job): Promise<void> {
256	  const volume = await loadVolume(job);
257	  const server = volume.server;
258	
259	  if (SANDBOX) {
260	    await db.volume.delete({ where: { id: volume.id } });
261	    await notify(volume.userId, `Volume "${volume.name}" deleted`, undefined, "/dashboard/volumes");
262	    return;
263	  }
264	
265	  if (server?.vmid && volume.diskName) {
266	    const { conn } = await nodeFor(server);
267	    try {
268	      let config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
269	      let key = keyForVolid(config, volume.diskName);
270	
271	      // If still mounted, detach to an "unused" entry first.
272	      if (key && key.startsWith("scsi")) {
273	        await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
274	        config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
275	        key = keyForVolid(config, volume.diskName);
276	      }
277	      // Deleting an "unused" entry destroys the underlying disk.
278	      if (key) {
279	        await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
280	      }
281	    } catch (e: any) {
282	      const msg = String(e?.body ?? e?.message ?? e);
283	      if (!msg.includes("does not exist")) throw e;
284	    }
285	  }
286	
287	  await db.volume.delete({ where: { id: volume.id } });
288	  await notify(volume.userId, `Volume "${volume.name}" deleted`, undefined, "/dashboard/volumes");
289	}
