78	  let servers: Array<{ id: string; vmid: number | null; node: any; extraDiskGB: number; plan: { diskGB: number } }>;
79	  try {
80	    servers = await db.server.findMany({
81	      where: { status: "RUNNING", vmid: { not: null } },
82	      select: {
83	        id: true,
84	        vmid: true,
85	        extraDiskGB: true,
86	        plan: { select: { diskGB: true } },
87	        node: {
88	          select: { pveNode: true, apiUrl: true, tokenId: true, tokenSecret: true },
89	        },
90	      },
91	    });
92	  } catch (e) {
93	    console.error("[monitor] disk-sample: list servers error", e);
94	    return;
95	  }
