/**
 * Read-only helper for per-server disk time-series from Proxmox RRD.
 * Kept out of "use server" files so it can be imported by the API route.
 * Uses the node-aware pveFor() when the server is pinned to a Node row,
 * otherwise falls back to the default single-node client.
 */
import { pve, node as defaultNode, pveFor, type NodeConn } from "@/lib/proxmox";

export type DiskPoint = { time: number; disk: number | null; maxdisk: number | null };

const VALID_TF = ["hour", "day", "week", "month", "year"];

/**
 * Fetch the disk RRD series for a VM. `disk` = bytes used as seen by the
 * hypervisor, `maxdisk` = provisioned size. Note: for QEMU guests Proxmox
 * often cannot see in-guest usage, so `disk` may be 0/null — callers should
 * fall back to the provisioned/plan size for the "total".
 */
export async function serverDiskRrd(
  vmid: number,
  timeframe: string,
  conn?: NodeConn | null
): Promise<DiskPoint[]> {
  const tf = VALID_TF.includes(timeframe) ? timeframe : "day";
  let raw: any[];
  if (conn) {
    const client = pveFor(conn);
    raw = await client.get(`/nodes/${conn.pveNode}/qemu/${vmid}/rrddata`, {
      timeframe: tf,
      cf: "AVERAGE",
    });
  } else {
    raw = await pve.get(`/nodes/${defaultNode}/qemu/${vmid}/rrddata`, { timeframe: tf, cf: "AVERAGE" });
  }
  return (raw ?? [])
    .filter((r) => r && typeof r.time === "number")
    .map((r) => ({
      time: r.time,
      disk: typeof r.disk === "number" ? r.disk : null,
      maxdisk: typeof r.maxdisk === "number" ? r.maxdisk : null,
    }));
}

