export async function workerHealth(): Promise<WorkerHealth> {
  const now = Date.now();
  const [newest, stuckRunning, queuedBacklog, staleQueued] = await Promise.all([
    db.job.findFirst({ orderBy: { updatedAt: "desc" }, select: { updatedAt: true } }),
    db.job.count({ where: { status: "RUNNING", updatedAt: { lt: new Date(now - STUCK_JOB_MS) } } }),
    db.job.count({ where: { status: "QUEUED" } }),
    db.job.count({ where: { status: "QUEUED", createdAt: { lt: new Date(now - WORKER_STALE_MS) } } }),
  ]);

  let status: CompStatus = "operational";
  let detail = newest
    ? `last job update ${fmtAge(now - newest.updatedAt.getTime())} ago`
    : "idle — no jobs processed yet";

  if (staleQueued > 0) {
    status = "down";
    detail = `${staleQueued} job(s) queued but not picked up — worker may be stopped`;
  } else if (stuckRunning > 0) {
    status = "degraded";
    detail = `${stuckRunning} job(s) stuck running > ${Math.round(STUCK_JOB_MS / 60_000)}m`;
  }

  return {
    status,
    detail,
    newestUpdatedAt: newest?.updatedAt ?? null,
    stuckRunning,
    queuedBacklog,
    staleQueued,
  };
}

