=== EXTRA-DISK ===
/**
 * Per-server extra disk — pure, dependency-free maths + copy.
 *
 * Deliberately has NO server-only imports (no db, no settings) so the exact same
 * module can be imported by client components (DeployWizard, AddStorage) and by
 * the server actions / worker. Whatever the customer SEES is byte-for-byte what
 * gets CHARGED — mirroring lib/wallet-split.ts.
 *
 * This is the server's OWN root disk growing, which is a different product from
 * block-storage volumes (lib/actions-volumes.ts): a volume is portable and can be
 * detached and deleted; this space is fused into the VM's root filesystem.
 *
 * ─── GROWTH IS ONE-WAY ──────────────────────────────────────────────────────
 * A live filesystem cannot be shrunk without risking data loss, and no serious
 * provider offers it. There is NO shrink path anywhere in the platform, and
 * `Server.extraDiskGB` is never decremented. Every surface that sells extra
 * storage must show EXTRA_DISK_ONE_WAY_NOTE before taking the money.
 */

/** Storage is sold in 10 GB increments — matches the slider/step in both UIs. */
export const EXTRA_DISK_STEP_GB = 10;
/** Smallest purchasable amount. */
export const EXTRA_DISK_MIN_GB = 10;
/** Largest amount purchasable in a SINGLE transaction. */
export const EXTRA_DISK_MAX_ADD_GB = 500;
/** Hard ceiling on a server's effective disk (plan.diskGB + extraDiskGB). */
export const EXTRA_DISK_MAX_TOTAL_GB = 2000;
/**
 * Fallback price per GB per month when the `extra_disk_gb_price_cents` admin
 * setting has never been written. 10 = $0.10/GB/mo, matching block storage.
 * Use `extraDiskMonthlyCents()` (lib/disk-expand.ts) in billing paths, never this.
 */
export const EXTRA_DISK_DEFAULT_PER_GB_CENTS = 10;

/** The one-way warning, shown verbatim on every surface that sells extra disk. */
export const EXTRA_DISK_ONE_WAY_NOTE =
  "Storage can only be added, never removed. Extra disk space is permanent for this server's lifetime and keeps billing every cycle.";

/** A server's EFFECTIVE root disk in GB — plan allowance plus purchased extra. */
export function effectiveDiskGB(planDiskGB: number, extraDiskGB: number | null | undefined): number {
  return Math.max(0, Math.round(planDiskGB)) + Math.max(0, Math.round(extraDiskGB ?? 0));
}

/**
 * Monthly cost (integer cents) of `gb` extra GB at `perGbCents`. Exact integer
 * multiplication — no floating-point money.
 */
export function extraDiskCentsAt(gb: number, perGbCents: number): number {
  const g = Math.max(0, Math.round(gb));
  const p = Math.max(0, Math.round(perGbCents));
  return g * p;
}

/** Is `gb` a purchasable amount (a positive multiple of the step, within range)? */
export function isValidExtraDiskAddGB(gb: number): boolean {
  return (
    Number.isInteger(gb) &&
    gb >= EXTRA_DISK_MIN_GB &&
    gb <= EXTRA_DISK_MAX_ADD_GB &&
    gb % EXTRA_DISK_STEP_GB === 0

